//! The string escaping of `sermofur_core::json` against the table that the .NET encoder produced
//! (`rust/tests/golden/json-escape.json`, regenerated by `rust/tools/escape-oracle`).

use std::collections::HashMap;

use serde_json::Value;
use sermofur_core::json::to_string;

fn golden() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/golden/json-escape.json"
    );
    let text = std::fs::read_to_string(path).expect("the golden file exists");
    serde_json::from_str(&text).expect("the golden file is valid JSON")
}

/// The JSON text of a one-character string, without its quotes.
fn escaped_form(text: &str) -> String {
    let json = to_string(text).expect("a string always serializes");
    json[1..json.len() - 1].to_string()
}

fn scalar_of(value: &Value) -> u32 {
    u32::try_from(value.as_u64().expect("a number")).expect("a scalar value fits in u32")
}

fn pair(value: &Value) -> (u32, String) {
    let text = value[1].as_str().expect("an escaped text");
    (scalar_of(&value[0]), text.to_string())
}

#[test]
fn every_basic_plane_scalar_is_escaped_like_the_dotnet_encoder() {
    let golden = golden();
    let specials: HashMap<u32, String> = golden["escapedBmp"]["specials"]
        .as_array()
        .expect("specials")
        .iter()
        .map(pair)
        .collect();
    let ranges: Vec<(u32, u32)> = golden["escapedBmp"]["unicodeEscapedRanges"]
        .as_array()
        .expect("ranges")
        .iter()
        .map(|range| (scalar_of(&range[0]), scalar_of(&range[1])))
        .collect();

    let mut mismatches: Vec<String> = Vec::new();
    for scalar in 0..=0xFFFFu32 {
        let Some(c) = char::from_u32(scalar) else {
            continue; // A surrogate: no Rust string can hold it.
        };
        let text = c.to_string();
        let expected = if let Some(special) = specials.get(&scalar) {
            special.clone()
        } else if ranges
            .iter()
            .any(|&(start, end)| (start..=end).contains(&scalar))
        {
            format!("\\u{scalar:04X}")
        } else {
            text.clone()
        };
        let actual = escaped_form(&text);
        if actual != expected {
            mismatches.push(format!("U+{scalar:04X}: expected {expected}, got {actual}"));
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} mismatches, first: {:?}",
        mismatches.len(),
        &mismatches[..mismatches.len().min(5)]
    );
}

#[test]
fn supplementary_samples_are_surrogate_pairs() {
    let golden = golden();
    let samples = golden["supplementarySamples"].as_array().expect("samples");
    assert!(samples.len() > 100, "the golden file holds the samples");
    for sample in samples {
        let (scalar, expected) = pair(sample);
        let c = char::from_u32(scalar).expect("a scalar value");
        assert_eq!(escaped_form(&c.to_string()), expected, "U+{scalar:X}");
    }
}
